 select {
 case <-output.entered: admitted = true
 case err := <-refused: if err != b.ErrBusy { panic(err) }
 }
 active := 1
 if admitted { active++ }
 fmt.Printf("running=%d limit=1\n", active)
 close(output.release)
 <-finished
 if admitted { <-refused }
