timeout 20 sh -c 'd=$(mktemp -d "${TMPDIR:-/tmp}/tpp-f39-profile-backfill-XXXXXX") && cat > "$d/main.go" <<"GO"
package main
import (
 "context"
 "fmt"
 b "profilebackfill"
)
func main() {
 repo := b.NewRepository([]b.Profile{{ID:"a", Handle:"amy"}, {ID:"b", Handle:"ben"}})
 index := b.NewIndex()
 worker := b.NewWorker(repo, b.NewRegistry(1), index)
 worker.Warm()
 plan, err := worker.Run(context.Background(), b.Options{Preview:true})
 if err != nil { panic(err) }
 rows := repo.Snapshot()
 pending, attempts := 0, 0
 for _, row := range rows { if row.State == "pending" { pending++ }; attempts += row.Attempts }
 applied, err := worker.Run(context.Background(), b.Options{})
 if err != nil { panic(err) }
 fmt.Printf("preview=%d pending=%d attempts=%d applied=%d indexed=%d\n", len(plan.Cards), pending, attempts, applied.Applied, len(index.Cards()))
}
GO
go run "$d/main.go"'
